"use strict";
import { useQuery } from "@tanstack/react-query";
import { useAccount } from "hooks/useAccount";
import { Contract } from "@ethersproject/contracts";
import { useEthersProvider } from "hooks/useEthersProvider";
import { UniverseChainId } from "uniswap/src/features/chains/types";
import { useVoterReads } from "./useVoterContract";
import { getContractAddress, getContractAbi } from "uniswap/src/constants/contracts";
import { useAppSelector } from "state/hooks";
import { selectPendingVotes, selectSelectedLock } from "state/voting/slice";
const MULTICALL3_ADDRESS = "0xcA11bde05977b3631167028862bE2a173976CA11";
const MULTICALL3_ABI = [
  {
    inputs: [
      {
        components: [
          { internalType: "address", name: "target", type: "address" },
          { internalType: "bytes", name: "callData", type: "bytes" }
        ],
        internalType: "struct Multicall3.Call[]",
        name: "calls",
        type: "tuple[]"
      }
    ],
    name: "aggregate",
    outputs: [
      { internalType: "uint256", name: "blockNumber", type: "uint256" },
      { internalType: "bytes[]", name: "returnData", type: "bytes[]" }
    ],
    stateMutability: "payable",
    type: "function"
  }
];
const VOTER_LAST_VOTED_ABI = [
  {
    inputs: [{ internalType: "uint256", name: "", type: "uint256" }],
    name: "lastVoted",
    outputs: [{ internalType: "uint256", name: "", type: "uint256" }],
    stateMutability: "view",
    type: "function"
  }
];
export function useVotingStatus(locks) {
  const account = useAccount();
  const chainId = account.chainId || UniverseChainId.Mainnet;
  const provider = useEthersProvider({ chainId });
  const { epochStart } = useVoterReads();
  const pendingVotes = useAppSelector(selectPendingVotes);
  const selectedLock = useAppSelector(selectSelectedLock);
  const votingStatusQuery = useQuery({
    queryKey: ["voting-status", locks?.map((l) => l.id).join(","), chainId, epochStart],
    queryFn: async () => {
      if (!locks || locks.length === 0) return [];
      try {
        if (!provider) {
          throw new Error("Provider not available");
        }
        const currentChainId = chainId || UniverseChainId.Mainnet;
        const voterAddress = getContractAddress(currentChainId, "Voter");
        const voterAbi = getContractAbi(currentChainId, "Voter");
        if (!voterAddress || !voterAbi) {
          throw new Error("Voter contract not available");
        }
        const multicall = new Contract(MULTICALL3_ADDRESS, MULTICALL3_ABI, provider);
        const voter = new Contract(voterAddress, voterAbi, provider);
        const currentTime = Date.now() / 1e3;
        const votingCalls = [];
        for (const lock of locks) {
          votingCalls.push({
            target: voterAddress,
            callData: voter.interface.encodeFunctionData("lastVoted", [BigInt(lock.id)])
          });
          votingCalls.push({
            target: voterAddress,
            callData: voter.interface.encodeFunctionData("usedWeights", [BigInt(lock.id)])
          });
        }
        const batchSize = 50;
        const allResults = [];
        for (let i = 0; i < votingCalls.length; i += batchSize) {
          const batch = votingCalls.slice(i, i + batchSize);
          try {
            const [, returnData] = await multicall.callStatic.aggregate(batch);
            for (let j = 0; j < returnData.length; j += 2) {
              try {
                const lastVotedResult = returnData[j];
                const usedWeightsResult = returnData[j + 1];
                const decodedLastVoted = voter.interface.decodeFunctionResult("lastVoted", lastVotedResult);
                const lastVotedTimestamp = Number(decodedLastVoted[0]);
                const hasVoted = epochStart ? lastVotedTimestamp >= epochStart : false;
                const decodedUsedWeights = voter.interface.decodeFunctionResult("usedWeights", usedWeightsResult);
                const usedWeights = BigInt(decodedUsedWeights[0]);
                allResults.push({ hasVoted, usedWeights });
              } catch (error) {
                console.error("Error decoding voting status result:", error);
                allResults.push({ hasVoted: false, usedWeights: 0n });
              }
            }
          } catch (error) {
            console.error("Voting status multicall batch failed:", error);
            const lockStartIndex = Math.floor(i / 2);
            const locksInBatch = Math.ceil(batch.length / 2);
            for (let j = 0; j < locksInBatch; j++) {
              const lockIndex = lockStartIndex + j;
              if (lockIndex >= locks.length) break;
              try {
                const lock = locks[lockIndex];
                const lastVotedTimestamp = await voter.lastVoted(BigInt(lock.id));
                const lastVotedNumber = Number(lastVotedTimestamp);
                const hasVoted = epochStart ? lastVotedNumber >= epochStart : false;
                const usedWeightsValue = await voter.usedWeights(BigInt(lock.id));
                const usedWeights = BigInt(usedWeightsValue);
                allResults.push({ hasVoted, usedWeights });
              } catch (individualError) {
                console.error(`Individual call failed for lock ${locks[lockIndex]?.id}:`, individualError);
                allResults.push({ hasVoted: false, usedWeights: 0n });
              }
            }
          }
        }
        const finalResults = locks.map((lock, index) => {
          const result = allResults[index] || { hasVoted: false, usedWeights: 0n };
          const { hasVoted, usedWeights } = result;
          const hasLingeringVotes = !hasVoted && usedWeights > 0n;
          return {
            tokenId: lock.id,
            hasVoted,
            // Voted in current epoch (cannot reset)
            hasLingeringVotes,
            // Has unreset votes from previous epoch (can reset)
            usedWeights,
            // Raw usedWeights value
            allocatedPercentage: 0,
            // Will be calculated outside the query
            remainingPercentage: 100,
            isFullyAllocated: false
          };
        });
        return finalResults;
      } catch (error) {
        console.error("Failed to check voting status:", error);
        return locks.map((lock) => {
          return {
            tokenId: lock.id,
            hasVoted: false,
            hasLingeringVotes: false,
            usedWeights: 0n,
            allocatedPercentage: 0,
            remainingPercentage: 100,
            isFullyAllocated: false,
            error: "Failed to check voting status"
          };
        });
      }
    },
    enabled: !!locks && locks.length > 0 && !!chainId && !!provider,
    refetchInterval: 3e4,
    // Refetch every 30 seconds
    staleTime: 15e3,
    // Consider data stale after 15 seconds
    placeholderData: (previousData) => previousData,
    // Keep previous data while loading
    refetchOnWindowFocus: false
    // Prevent unnecessary refetches on window focus
  });
  const lockStatusesWithAllocation = (votingStatusQuery.data || []).map((status) => {
    let allocatedPercentage = 0;
    if (selectedLock?.id === status.tokenId) {
      allocatedPercentage = pendingVotes.reduce((total, vote) => total + (vote.percentage || 0), 0);
    }
    const remainingPercentage = Math.max(0, 100 - allocatedPercentage);
    const isFullyAllocated = allocatedPercentage >= 100;
    return {
      ...status,
      allocatedPercentage,
      remainingPercentage,
      isFullyAllocated
    };
  });
  return {
    lockStatuses: lockStatusesWithAllocation,
    isLoading: votingStatusQuery.isLoading,
    isRefetching: votingStatusQuery.isRefetching,
    error: votingStatusQuery.error?.message,
    refetch: votingStatusQuery.refetch
  };
}
export function useLockVotingStatus(tokenId) {
  const locks = tokenId ? [{ id: tokenId }] : void 0;
  const { lockStatuses, isLoading, error } = useVotingStatus(locks);
  return {
    tokenId: tokenId || "",
    hasVoted: lockStatuses[0]?.hasVoted || false,
    hasLingeringVotes: lockStatuses[0]?.hasLingeringVotes || false,
    usedWeights: lockStatuses[0]?.usedWeights || 0n,
    allocatedPercentage: lockStatuses[0]?.allocatedPercentage || 0,
    remainingPercentage: lockStatuses[0]?.remainingPercentage || 100,
    isFullyAllocated: lockStatuses[0]?.isFullyAllocated || false,
    isLoading,
    error
  };
}
export const VotingStatusUtils = {
  /**
   * Filter locks that haven't voted yet
   */
  filterUnvotedLocks: (locks, statuses) => {
    const statusMap = new Map(statuses.map((s) => [s.tokenId, s.hasVoted]));
    return locks.filter((lock) => !statusMap.get(lock.id));
  },
  /**
   * Filter locks that have already voted
   */
  filterVotedLocks: (locks, statuses) => {
    const statusMap = new Map(statuses.map((s) => [s.tokenId, s.hasVoted]));
    return locks.filter((lock) => statusMap.get(lock.id));
  },
  /**
   * Get voting status summary
   */
  getVotingStatusSummary: (statuses) => {
    const total = statuses.length;
    const voted = statuses.filter((s) => s.hasVoted).length;
    const unvoted = total - voted;
    return {
      total,
      voted,
      unvoted,
      votedPercentage: total > 0 ? Math.round(voted / total * 100) : 0
    };
  }
};
